// 2 的冪在二進位中只有一個 1：n & (n - 1) 會等於 0
// 時間複雜度: O(1)，空間複雜度: O(1)
function isPowerOfTwo(n) {
    return n > 0 && (n & (n - 1)) === 0;
}

solutions.python:
# 方法一：n & (n-1) == 0（推薦）
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        return n > 0 and (n & (n - 1)) == 0


# 方法二：n & (-n) == n
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        return n > 0 and (n & -n) == n


# 方法三：數學法（不用迴圈/遞迴）
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        return n > 0 and (1 << 30) % n == 0


# 方法四：迴圈除法（最直覺）
class Solution:
    def isPowerOfTwo(self, n: int) -> bool:
        if n <= 0:
            return False
        while n % 2 == 0:
            n //= 2
        return n == 1

solutions.cpp:
// 方法一：n & (n-1) == 0（推薦）
class Solution {
public:
    bool isPowerOfTwo(int n) {
        return n > 0 && (n & (n - 1)) == 0;
    }
};

// 方法二：n & (-n) == n
class Solution {
public:
    bool isPowerOfTwo(int n) {
        if (n <= 0) return false;
        // 用 long long 避免 INT_MIN 取負號溢位
        long long x = n;
        return (x & -x) == x;
    }
};

// 方法三：數學法（不用迴圈/遞迴）
class Solution {
public:
    bool isPowerOfTwo(int n) {
        return n > 0 && (1 << 30) % n == 0;
    }
};

